INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Framework dasselbe wie eine Programmiersprache?', 2, '[{"text": "Nein", "correct": true, "because": "Gerüst vs. Sprache"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Konzepte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt ein Framework?', 3, '[{"text": "Entwicklung effizienter gestalten", "correct": true, "because": "Vorfertige Komponenten"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Nicht primär"}, {"text": "Hardware optimieren", "correct": false, "because": "Softwarefokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele sind Frameworks?', 5, '[{"text": "Spring", "correct": true, "because": "Java Framework"}, {"text": "Django", "correct": true, "because": "Python Web Framework"}, {"text": "Notepad", "correct": false, "because": "Texteditor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Framework bietet vorgefertigte Funktionen. b) Es ersetzt Programmiersprachen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ergänzt Sprachen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Framework?', 4, '[{"text": "Bibliotheken", "correct": false, "because": "Kernbestandteil"}, {"text": "Dokumentation", "correct": false, "because": "Nutzungshilfe"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Framework immer Open-Source ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch proprietär"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Framework ist für Webanwendungen typisch?', 3, '[{"text": "React", "correct": true, "because": "Frontend Framework"}, {"text": "Apache", "correct": false, "because": "Webserver"}, {"text": "MySQL", "correct": false, "because": "Datenbank"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Framework?', 5, '[{"text": "Zeitersparnis", "correct": true, "because": "Vorfertige Lösungen"}, {"text": "Wiederverwendbarkeit", "correct": true, "because": "Modularität"}, {"text": "Papierersparnis", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Frameworks beschleunigen die Entwicklung. b) Sie sind nur für Anfänger. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Für alle Entwickler"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Framework?', 4, '[{"text": "Programmiersprache", "correct": false, "because": "Basis"}, {"text": "API-Dokumentation", "correct": false, "because": "Nutzungshilfe"}, {"text": "Physisches Handbuch", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Framework immer plattformunabhängig?', 2, '[{"text": "Nein", "correct": true, "because": "Plattformabhängig möglich"}, {"text": "Ja", "correct": false, "because": "Variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Frameworks gibt es?', 4, '[{"text": "Web-Frameworks", "correct": true, "because": "Z. B. Flask"}, {"text": "Test-Frameworks", "correct": true, "because": "Z. B. JUnit"}, {"text": "Papier-Frameworks", "correct": false, "because": "Kein Typ"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Frameworks die Entwicklung erschweren. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Vereinfachen"}, {"text": "Ja", "correct": false, "because": "Zeitersparnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Framework?', 3, '[{"text": "Effizienz", "correct": true, "because": "Entwicklungszeit"}, {"text": "Schriftart", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Funktionalität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Frameworks bieten Struktur. b) Sie sind nur für kleine Projekte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch große Projekte"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile kann ein Framework haben?', 5, '[{"text": "Lernkurve", "correct": true, "because": "Komplexität"}, {"text": "Abhängigkeit", "correct": true, "because": "Vendor Lock-in"}, {"text": "Papierverbrauch", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Framework unwichtig?', 3, '[{"text": "Code-Struktur", "correct": false, "because": "Grundlage"}, {"text": "Dokumentation", "correct": false, "because": "Nutzungshilfe"}, {"text": "Papiergröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Framework die Entwicklungskosten senken?', 3, '[{"text": "Ja", "correct": true, "because": "Weniger Eigenentwicklung"}, {"text": "Nein", "correct": false, "because": "Kostenersparnis möglich"}]'),
